    seen=np.zeros_like(I,bool); comps=[]
    for y in range(H):
        for x in range(W):
            if I[y,x]!=bg and not seen[y,x]:
                st=[(y,x)];seen[y,x]=True;cells=[]
                while st:
                    yy,xx=st.pop();cells.append((yy,xx))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=yy+dy,xx+dx
                        if 0<=ny<H and 0<=nx<W and I[ny,nx]!=bg and not seen[ny,nx]:
                            seen[ny,nx]=True;st.append((ny,nx))
                comps.append(cells)
    tmpl={}; used=set()
    for c in comps:
        if len(c)<2: continue
        vals=sorted(set(int(I[a,b]) for a,b in c))
        anchor=None
        for v in vals:
            n=sum(1 for a,b in c if I[a,b]==v)
            if n==1:
                anch=[(a,b) for a,b in c if I[a,b]==v][0]
                rel=[(a-anch[0],b-anch[1],int(I[a,b])) for a,b in c if (a,b)!=anch]
                tmpl[v]=rel
                for a,b in c: used.add((a,b))
                anchor=v; break
        if anchor is None:
            for a,b in c: used.add((a,b))
    res=I.copy()
    for y in range(H):
        for x in range(W):
            v=int(I[y,x])
            if v==bg or (y,x) in used or v not in tmpl: continue
