            if horizmirror_for_2 and v==2: rel=[(dy,-dx,cv) for dy,dx,cv in rel]
            for dy,dx,cv in rel:
                ny,nx=y+dy,x+dx
                if 0<=ny<H and 0<=nx<W and res[ny,nx]==bg:
                    res[ny,nx]=cv
    return res
